with open(path, "r", encoding="utf-8") as f:
    content = f.read()

match = re.search(r"turnRight:\s*\[(.*?)\]", content, re.DOTALL)
if match:
    block = match.group(1)
    lines = [line.strip().strip("\"").strip(",") for line in block.split("\n") if line.strip()]

    # First pass: find all hashes and their positions
    row_spans = []
    for l in lines:
        hashes = [i for i, c in enumerate(l) if c == "#"]
        if hashes:
            row_spans.append((hashes[0], hashes[-1] if len(hashes) > 1 else None))
        else:
            row_spans.append((None, None))

    # If a row has only one hash (left), let's infer right hash from neighbors or max right hash of active rows
    filled_lines = []
    for idx, l in enumerate(lines):
        hashes = [i for i, c in enumerate(l) if c == "#"]
        if not hashes:
            filled_lines.append(l)
            continue
        left = hashes[0]
        if len(hashes) > 1:
            right = hashes[-1]
        else:
            # infer right from nearby rows with 2+ hashes
            right = 31 # default or neighbor lookup
            for d in range(1, len(lines)):
                for neighbor_idx in (idx - d, idx + d):
                    if 0 <= neighbor_idx < len(row_spans) and row_spans[neighbor_idx][1] is not None:
                        right = row_spans[neighbor_idx][1]
                        break
                else:
                    continue
                break
        new_l = l[:left] + "#" * (right - left + 1) + l[right+1:]
        filled_lines.append(new_l)

    for f_line in filled_lines:
        print(f"        \"{f_line}\",")
