    hiEl.textContent = `HI: ${hi}`;
    let gameInterval = null;
    let gameState = "START";

    const resetGame = () => {
      snake = [
        { x: 7, y: 7 },
        { x: 6, y: 7 },
        { x: 5, y: 7 }
      ];
      dx = 0;
      dy = 0;
      score = 0;
