        ".........##############.........",
        "........################........",
        ".......##################.......",
        "......####################......",
        ".....######################.....",
        ".....#####.OO.####.OO.#####.....",
        ".....#####.EE.####.EE.#####.....",
        ".....#######################....",
        ".....#######################....",
