    const rotateSprite = (sprite, times) => {
      let grid = sprite.map(row => row.split(''));
      for (let t = 0; t < times; t++) {
        const n = grid.length;
        const rotated = Array.from({ length: n }, () => Array(n).fill('.'));
        for (let r = 0; r < n; r++) {
          for (let c = 0; c < n; c++) {
            rotated[c][n - 1 - r] = grid[r][c];
          }
        }
        grid = rotated;
