    let snake = [];
    let food = { x: 5, y: 5 };
    let dx = 0;
    let dy = 0;
    let score = 0;
    let hi = parseInt(localStorage.getItem("cyber_snake_hi") || "0", 10);
    hiEl.textContent = `HI: ${hi}`;
    let gameInterval = null;
    let gameState = "START";

    const resetGame = () => {
      snake = [
        { x: 7, y: 7 },
        { x: 6, y: 7 },
        { x: 5, y: 7 }
      ];
      dx = 0;
      dy = 0;
      score = 0;
      scoreEl.textContent = `SCORE: ${score}`;
      spawnFood();
    };

    const spawnFood = () => {
      food = {
