        "..........############..........",
        ".........##############.........",
        "........################........",
        ".......##################.......",
        "......####################......",
        ".....######################.....",
        ".....#####.OO.####.OO.#####.....",
        ".....#####.EE.####.EE.#####.....",
        ".....#######################....",
        ".....#######################....",
        "......#####################.....",
        "......#####################.....",
        ".......###################......",
        "........################........",
        "........################........",
        ".........##############.........",
        "..........############..........",
        "...........##########...........",
        "............########............",
