        ".....###.#####....#####.###.....",
        ".....##########..##########....."
      ],
      tail: [
        ".....###.######..######.###.....",
        ".....####.####.##.####.####.....",
        ".....#####.####..####.#####.....",
        ".....######.########.######.....",
        ".....#####.#.######.#.#####.....",
