        ".....#####.####..####.#####.....",
        ".....######.########.######.....",
        ".....#####.#.######.#.#####.....",
        ".....####.###.####.###.####.....",
        ".....###.#####....#####.###.....",
        ".....##########..##########....."
      ],
      tail: [
        ".....###.######..######.###.....",
        ".....####.####.##.####.####.....",
        ".....#####.####..####.#####.....",
        ".....######.########.######.....",
        ".....#####.#.######.#.#####.....",
        ".....####.###.####.###.####.....",
        ".....###.#####....#####.###.....",
        ".....##########..##########.....",
        "......####################......",
        "......####################......",
        ".......##################.......",
        ".......##################.......",
        "........################........",
        "........################........",
        ".........##############.........",
        ".........##############.........",
        "..........############..........",
        "..........############..........",
        "...........##########...........",
        "...........##########...........",
        "............########............",
        "............########............",
        ".............######.............",
        ".............######.............",
        "..............####..............",
        "..............####..............",
        "...............##...............",
        "...............##...............",
        "................................",
        "................................",
        "................................",
        "................................"
      ],
      turn: [
        "................................",
        "................................",
        "................................",
        "................................",
        "................................",
        "...........#####################",
        ".........#######################",
        "........########################",
        ".......#########################",
        "......##########################",
        "......##########################",
