        ".....#####.####..####.#####.....",
        ".....######.########.######.....",
        ".....#####.#.######.#.#####.....",
        ".....####.###.####.###.####.....",
        ".....###.#####....#####.###.....",
        ".....##########..##########.....",
        ".....###.######..######.###.....",
        ".....####.####.##.####.####.....",
        ".....#####.####..####.#####.....",
        ".....######.########.######.....",
        ".....#####.#.######.#.#####.....",
        ".....####.###.####.###.####.....",
        ".....###.#####....#####.###.....",
        ".....##########..##########.....",
        ".....###.######..######.###.....",
        ".....####.####.##.####.####.....",
        ".....#####.####..####.#####.....",
        ".....######.########.######.....",
        ".....#####.#.######.#.#####.....",
        ".....####.###.####.###.####.....",
        ".....###.#####....#####.###.....",
        ".....##########..##########....."
      ],
      tail: [
        ".....###.######..######.###.....",
        ".....####.####.##.####.####.....",
        ".....#####.####..####.#####.....",
        ".....######.########.######.....",
        ".....#####.#.######.#.#####.....",
        ".....####.###.####.###.####.....",
        ".....###.#####....#####.###.....",
        ".....##########..##########.....",
        "......####################......",
        "......####################......",
        ".......##################.......",
        ".......##################.......",
        "........################........",
        "........################........",
        ".........##############.........",
        ".........##############.........",
        "..........############..........",
