    sprites.headRight = rotateSprite(sprites.head, 1);
    sprites.headDown = rotateSprite(sprites.head, 2);
    sprites.headLeft = rotateSprite(sprites.head, 3);

    sprites.tailDown = sprites.tail;
    sprites.tailRight = rotateSprite(sprites.tail, 1);
    sprites.tailUp = rotateSprite(sprites.tail, 2);
    sprites.tailLeft = rotateSprite(sprites.tail, 3);

    sprites.bodyVertical = sprites.body;
    sprites.bodyHorizontal = rotateSprite(sprites.body, 1);

    const vertGrid = sprites.body.map(row => row.split(''));
    const horizGrid = sprites.bodyHorizontal.map(row => row.split(''));
    const baseTurn = sprites.turn.map(row => row.split(''));
    const turnR = Array.from({ length: 32 }, () => Array(32).fill('.'));
    for (let r = 0; r < 32; r++) {
      for (let c = 0; c < 32; c++) {
        if (baseTurn[r][c] === '#') {
          let pVert = vertGrid[r][c];
          let pHoriz = horizGrid[r][c];
          if (pVert !== '.') {
            turnR[r][c] = pVert;
          } else if (pHoriz !== '.') {
            turnR[r][c] = pHoriz;
          } else {
            turnR[r][c] = '.';
          }
        }
      }
    }
    sprites.turnRight = turnR.map(row => row.join(''));
    sprites.turnLeft = sprites.turnRight.map(row => row.split('').reverse().join(''));

    sprites.turnRightUp = sprites.turnRight;
    sprites.turnRightRight = rotateSprite(sprites.turnRight, 1);
    sprites.turnRightDown = rotateSprite(sprites.turnRight, 2);
    sprites.turnRightLeft = rotateSprite(sprites.turnRight, 3);

    sprites.turnLeftUp = sprites.turnLeft;
    sprites.turnLeftRight = rotateSprite(sprites.turnLeft, 1);
    sprites.turnLeftDown = rotateSprite(sprites.turnLeft, 2);
    sprites.turnLeftLeft = rotateSprite(sprites.turnLeft, 3);

    const drawSprite = (ctx, sprite, x, y, size, color, glowColor) => {
      const px = size / sprite.length;
      ctx.save();
      if (glowColor) {
        ctx.shadowColor = glowColor;
        ctx.shadowBlur = 8;
      }
      for (let r = 0; r < sprite.length; r++) {
        for (let c = 0; c < sprite[r].length; c++) {
          const ch = sprite[r][c];
          if (ch === '#') {
            ctx.fillStyle = color;
            ctx.fillRect(x + c * px, y + r * px, px + 0.5, px + 0.5);
          } else if (ch === 'O' || ch === 'E') {
            ctx.fillStyle = "#ffffff";
            ctx.fillRect(x + c * px, y + r * px, px + 0.5, px + 0.5);
          }
        }
      }
      ctx.restore();
    };

    const getThemeColors = () => {
      const style = getComputedStyle(document.body);
      return {
        ink: style.getPropertyValue('--ink').trim() || '#090b0a',
        line: style.getPropertyValue('--line').trim() || '#2b322d',
        green: style.getPropertyValue('--green').trim() || '#20ef4f',
        cyan: style.getPropertyValue('--cyan').trim() || '#91f3a8',
        paper: style.getPropertyValue('--paper').trim() || '#e9eee8'
      };
    };

    const draw = () => {
      const colors = getThemeColors();
      ctx.fillStyle = colors.ink;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.strokeStyle = colors.line;
      ctx.lineWidth = 0.5;
      for (let i = 0; i < tileCount; i++) {
        ctx.beginPath(); ctx.moveTo(i * grid, 0); ctx.lineTo(i * grid, canvas.height); ctx.stroke();
