        ".....##########..##########.....",
        ".....###.######..######.###.....",
        ".....####.####.##.####.####.....",
        ".....#####.####..####.#####.....",
        ".....######.########.######.....",
        ".....#####.#.######.#.#####.....",
        ".....####.###.####.###.####.....",
        ".....###.#####....#####.###.....",
        ".....##########..##########.....",
        ".....###.######..######.###.....",
        ".....####.####.##.####.####.....",
        ".....#####.####..####.#####.....",
        ".....######.########.######.....",
        ".....#####.#.######.#.#####.....",
        ".....####.###.####.###.####.....",
        ".....###.#####....#####.###.....",
        ".....##########..##########.....",
        ".....###.######..######.###.....",
        ".....####.####.##.####.####.....",
        ".....#####.####..####.#####.....",
        ".....######.########.######.....",
        ".....#####.#.######.#.#####.....",
        ".....####.###.####.###.####.....",
        ".....###.#####....#####.###.....",
        ".....##########..##########....."
      ],
      tail: [
        ".....###.######..######.###.....",
        ".....####.####.##.####.####.....",
        ".....#####.####..####.#####.....",
        ".....######.########.######.....",
        ".....#####.#.######.#.#####.....",
        ".....####.###.####.###.####.....",
        ".....###.#####....#####.###.....",
        ".....##########..##########.....",
        "......####################......",
        "......####################......",
        ".......##################.......",
        ".......##################.......",
        "........################........",
        "........################........",
        ".........##############.........",
        ".........##############.........",
        "..........############..........",
        "..........############..........",
        "...........##########...........",
        "...........##########...........",
        "............########............",
        "............########............",
        ".............######.............",
        ".............######.............",
        "..............####..............",
        "..............####..............",
        "...............##...............",
        "...............##...............",
        "................................",
