        ".###########..####..###########.",
        ".###...####..######..####...###.",
        "..####..##..##....##..##..####..",
        "...####....##..##..##....####...",
        "....####..####....####..####....",
        ".....###..############..###.....",
        ".....###..####....####..###.....",
        ".....###..###..##..###..###.....",
        ".....###..##..####..##..###.....",
        ".....###..###..##..###..###.....",
        ".....###..####....####..###.....",
        ".....###..############..###....."
      ],
      
      body: [
        ".....###..#####..#####..###.....",
        ".....###..####.##.####..###.....",
        ".....#####.####..####.#####.....",
        ".....######.########.######.....",
        ".....#####.#.######.#.#####.....",
