        "..........############..........",
        ".........##############.........",
        "........################........",
        ".......##################.......",
        "......####################......",
        ".....######################.....",
        ".....#####.OO.####.OO.#####.....",
        ".....#####.EE.####.EE.#####.....",
        ".....#######################....",
        ".....#######################....",
        "......#####################.....",
        "......#####################.....",
        ".......###################......",
        "........################........",
        "........################........",
        ".........##############.........",
        "..........############..........",
