        ".....#####.#.######.#.#####.....",
        ".....####.###.####.###.####.....",
        ".....###.#####....#####.###.....",
        ".....##########..##########....."
      ],
      tail: [
        ".....###.######..######.###.....",
        ".....####.####.##.####.####.....",
        ".....#####.####..####.#####.....",
        ".....######.########.######.....",
        ".....#####.#.######.#.#####.....",
        ".....####.###.####.###.####.....",
        ".....###.#####....#####.###.....",
        ".....##########..##########.....",
        "......####################......",
        "......####################......",
